--- Generate an inline SVG for an Octicon by name
-- @param name string The icon identifier (e.g. "shield", "alert", "terminal")
-- @param extra_classes string Optional CSS classes (e.g. "callout-icon")
-- @param size number Optional dimension override in pixels (defaults to 16)
-- @return string Raw HTML string containing the <svg> element, or nil if not found
function octicons.to_svg(name, extra_classes, size)
  if not name then return nil end
  local clean_name = name:gsub("^octicon%-", ""):gsub("^icon%-", "")
  local icon = octicons.icons[clean_name]
  if not icon then return nil end

  local cls = "octicon octicon-" .. clean_name
  if extra_classes and #extra_classes > 0 then
    cls = cls .. " " .. extra_classes
  end

  local width = size or icon.width
  local height = size or icon.height

  return string.format(
    '<svg class="%s" viewBox="0 0 %d %d" width="%d" height="%d" aria-hidden="true" fill="currentColor" style="display:inline-block;vertical-align:-0.15em;">%s</svg>',
    cls, icon.width, icon.height, width, height, icon.path
  )
end

return octicons
